import{_ as l,l as o,o as e,c as n,v as r,p as s,x as t,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"正则语言泵引理","description":"","frontmatter":{"title":"正则语言泵引理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pumping-lemma-regular.md","filePath":"cs/pumping-lemma-regular.md","lastUpdated":1789023840000}'),m={name:"cs/pumping-lemma-regular.md"};function c(u,a,_,E,A,f){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="正则语言泵引理" tabindex="-1">正则语言泵引理 <a class="header-anchor" href="#正则语言泵引理" aria-label="Permalink to &quot;正则语言泵引理&quot;">​</a></h1><div class="epigraph"><p>正则语言里足够长的串，必有一段可被抽成任意多次，语言仍收下；找不到这样的分解，就不是正则。</p><footer>—— 据 Bar-Hillel, Perles and Shamir, 1961；Sipser, Introduction to the Theory of Computation 整理</footer></div><p>上一课<a href="/cs/chomsky-hierarchy">Chomsky 层级</a>把正则放在 3 型，并声明负向证明留给本课。本课不重画包含链，也不重做<a href="/cs/nfa-dfa">NFA 与 DFA</a>的子集构造。缺口是：<strong>怎样证明某个具体 \\(L\\) 不是正则</strong>——泵引理是最常用的必要性质，不是刻画。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正向：给 DFA 或正则式，即证正则。负向：语言无穷，不能逐串检查。DFA 只有 \\(|Q|\\) 个状态，长于 \\(|Q|\\) 的接受串必在某状态上循环。抽出循环对应的子串 \\(y\\)，泵 \\(xy^kz\\) 仍走同一环。若某 \\(L\\) 对一切候选分解都能找出一个 \\(k\\) 使 \\(xy^kz\\notin L\\)，则 \\(L\\) 非正则。</p><p>标准例子：\\(\\{a^nb^n\\mid n\\ge 0\\}\\)。主干 CFG 课用括号匹配当「正则做不到」的直觉；本课把这句收成引理应用，不再谈记号流。</p><h3 id="泵引理不是充要条件" tabindex="-1">泵引理不是充要条件 <a class="header-anchor" href="#泵引理不是充要条件" aria-label="Permalink to &quot;泵引理不是充要条件&quot;">​</a></h3><p>满足可泵的语言不必正则。引理是「正则 \\(\\Rightarrow\\) 可泵」。证非正则用逆否。有些非正则语言狡猾地可泵，要用 Myhill–Nerode 或封闭性，那是后课。</p><p><span class="marginnote">Bar-Hillel–Perles–Shamir 给出泵引理的经典形式。Sipser 用博弈语言：对手给 \\(p\\)，你给 \\(w\\)，对手切 \\(xyz\\)，你选 \\(k\\)。写证明时不要漏量化顺序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固定泵长度 \\(p\\)。选 \\(w\\in L\\)、\\(|w|\\ge p\\)（通常取最能破坏计数的那条）。对任意满足 \\(|xy|\\le p\\)、\\(|y|\\ge 1\\) 的分解，指出某个 \\(k\\)（常取 \\(0\\) 或 \\(2\\)）使 \\(xy^kz\\notin L\\)。计数论证：循环落在 \\(a\\) 段则 \\(a,b\\) 个数不再相等。</p>',11)),(e(),s(h,null,{default:t(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DFA%5B%22DFA%20%E7%8A%B6%E6%80%81%E6%9C%89%E9%99%90%22%5D%20--%3E%20LOOP%5B%22%E9%95%BF%E4%B8%B2%E5%BF%85%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20LOOP%20--%3E%20PUMP%5B%22xy%5Ek%20z%20%E4%BB%8D%E6%8E%A5%E5%8F%97%22%5D%0A%20%20PUMP%20--%3E%20NEG%5B%22%E7%A0%B4%E5%9D%8F%E5%88%99%E9%9D%9E%E6%AD%A3%E5%88%99%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>不要把 \\(\\{ww\\mid w\\in\\{0,1\\}^*\\}\\) 强行用本课引理硬泵——它更自然是后课 CFL 泵或不封闭的材料。本课把 \\(a^nb^n\\) 与 \\(\\{a^{n^2}\\}\\) 一类做完即可。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>引理依赖<strong>有限记忆</strong>：循环是同一状态重访。若允许栈，同一串可以不被这段 \\(y\\) 破坏，所以 CFL 需要另一条泵引理。本课不提前写 Ogden。</p><p>词法器仍可识别标识符；泵的是语言类，不是「DFA 实现得笨」。有限语言都正则，泵引理对有限 \\(L\\) 真空成立（取 \\(p\\) 大于最长串）。</p><p>泵长度 \\(p\\) 依赖于语言（或 DFA 状态数），不依赖于你选的那条 \\(w\\) 之外的参数：先有 \\(p\\)，再选 \\(w\\)。写反了量化，证明是错的。词法器识别的标识符语言正则，泵不了「任意层括号」；那是下一层 CFG 的事，不要用本课引理去泵程序语法。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Myhill–Nerode，不用封闭性证非正则（下一课最小化之后才把封闭当工具使）。不把泵引理写成算法：选 \\(w\\) 需要人。后课默认：要从正则里排除，先尝试泵；失败再换等价类。</p><p>写证明时把「存在 \\(p\\)」放在最外层，再选 \\(w\\)，再应付所有切法。量化一乱，泵引理就变成错的组合游戏。后课 Myhill–Nerode 在泵失败时接棒。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正则 \\(\\Rightarrow\\) 长串可泵；逆否用于排除。</li><li>量化顺序是对手与你的博弈；\\(a^nb^n\\) 是标准靶。</li><li>可泵不是正则的充要条件。</li><li>出处：Bar-Hillel, Perles and Shamir, 1961；Sipser。</li></ul>',10))])}const k=l(m,[["render",c]]);export{P as __pageData,k as default};
